def _rewrite_list_item(tok: Dict[str, Any]) -> None:
    if not tok.get('children'):
        return

    first_child = tok['children'][0]
    if first_child.get('type') != 'paragraph':
        return

    # Try to get raw text from paragraph's children
    raw_text = None

    if first_child.get('children'):
        # Check if first grandchild is a text node
        text_child = first_child['children'][0]
        if text_child.get('type') == 'text':
            raw_text = text_child.get('raw', '')

    # If no raw text found in children, try the paragraph itself
    if not raw_text and 'raw' in first_child:
        raw_text = first_child['raw']

    if raw_text:
        match = TASK_LIST_ITEM.match(raw_text)
        if match:
            # This is a task list item
            checkbox = match.group(1)
            checked = checkbox.lower() == '[x]'

            # Remove the checkbox from the text
            new_text = raw_text[match.end():]

            # Update the raw text in the appropriate location
            if first_child.get('children') and first_child['children'][0].get('type') == 'text':
                first_child['children'][0]['raw'] = new_text
            else:
                first_child['raw'] = new_text

            # Mark this as a task list item
            tok['type'] = 'task_list_item'
            tok['checked'] = checked
